package mapper;import entity.KhachHang;import java.sql.ResultSet;import java.sql.SQLException;import java.time.LocalDate;import java.time.LocalDateTime;public class KhachHangMapper implements RowMapper<KhachHang> {    @Override    public KhachHang mapper(ResultSet rs) {        try {            String maKH = rs.getString("maKH");            String hoTen = rs.getString("hoTen");            String gioiTinh = rs.getString("gioiTinh");            LocalDate ngaySinh = Rs.date(rs, "ngaySinh");            String soDienThoai = rs.getString("soDienThoai");            String email = rs.getString("email");            String diaChi = rs.getString("diaChi");            String cccd = rs.getString("cccd");            String ghiChu = rs.getString("ghiChu");            String maNhom = rs.getString("maNhom");            String maChiNhanh = rs.getString("maChiNhanh");            String lyDoKham = rs.getString("lyDoKham");            String tienSuBenh = rs.getString("tienSuBenh");            String diUng = rs.getString("diUng");            String maBacSi = rs.getString("maBacSi");            String maTuVan = rs.getString("maTuVan");            int soLanKham = rs.getInt("soLanKham");            LocalDate lanKhamGanNhat = Rs.date(rs, "lanKhamGanNhat");            LocalDateTime ngayTao = Rs.dateTime(rs, "ngayTao");            return new KhachHang(maKH, hoTen, gioiTinh, ngaySinh, soDienThoai, email, diaChi, cccd, ghiChu, maNhom, maChiNhanh, lyDoKham, tienSuBenh, diUng, maBacSi, maTuVan, soLanKham, lanKhamGanNhat, ngayTao);        } catch (SQLException e) {            return null;        }    }}